	@Override
	@Transactional
	public Response getCredentialDetails(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException {
		try {
			
			UUID requestId = UUID.randomUUID();
			String uuidAsStringnotify11 = requestId.toString();
			
			Instant currentTime = Instant.now();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
			String formattedTime = currentTime.atZone(java.time.ZoneOffset.UTC).format(formatter);

			AbdmCredentialdDto abdmCredentialdDtoswer = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery(
							"select ddcds.client_id as \"clientId\", ddcds.client_secret as \"clientSecret\" ,ddcds.dev_url as \"devUrl\" ,"
									+ " unit.unit_name as \"name\", "
									+ " ddcds.healthidsbx_url as \"healthidsbxUrl\" , ddcds.dev_abdm_url as \"devAbdmUrl\",ddcds.xcm_id as \"xcmId\" ,ddcds.phrsbx_url as \"phrsbxUrl\" , "
									+ " ddcds.id as \"id\" , ddcds.alise_Name as \"aliseName\" , "
									+ " ddcds.gateway_url as \"gatewayUrl\",  "
									+ " ddcds.abhasbx_url as \"abhasbxUrl\" " + " from abdm.m_abdm_credential ddcds "
									+ " inner join public.m_unit_master unit on  unit.unit_id = ddcds.unit_id "
									+ " where ddcds.organization_id =:organizationId" + " and ddcds.unit_id =:unitId "
									+ " and ddcds.status ='A'")
					.setInteger("unitId", abdmCredentialdDto.getUnitId())
					.setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();

			JSONArray jsonArray = new JSONArray();
			JSONObject jsonObject = new JSONObject();
			jsonObject.put("clientId", abdmCredentialdDtoswer.getClientId());
			jsonObject.put("clientSecret", abdmCredentialdDtoswer.getClientSecret());
			jsonObject.put("grantType", "client_credentials");
			jsonArray.put(jsonObject);

			String requestJson = jsonArray.toString().replaceAll("[\\[\\]]", "");

			/*
			 * OkHttpClient client = new OkHttpClient().newBuilder().build(); MediaType
			 * mediaType = MediaType.parse("application/json");
			 */
			/*
			 * RequestBody body = RequestBody.create(mediaType, requestJson); Request
			 * request = new Request.Builder().url(abdmCredentialdDtoswer.getDevAbdmUrl() +
			 * "/v3/sessions") .method("POST", body).addHeader("Content-Type",
			 * "application/json") .addHeader("Cookie",
			 * "TS011c04bd=01445fed043cb96b1a405b5d7d8778ec346ec2ed8c6f8860d192d25b6a6a052543bc06fe6815b487e9b1a863c3ac529b1615d19190")
			 * .addHeader("REQUEST-ID", uuidAsStringnotify11) .addHeader("TIMESTAMP",
			 * formattedTime) .addHeader("X-CM-ID", abdmCredentialdDtoswer.getXcmId())
			 * .build();
			 */
			
			OkHttpClient client = new OkHttpClient().newBuilder()
					  .build();
					MediaType mediaType = MediaType.parse("application/json");
					RequestBody body = RequestBody.create(mediaType, requestJson);
					Request request = new Request.Builder()
					  .url(abdmCredentialdDtoswer.getDevAbdmUrl()+"/v3/sessions")
					  .method("POST", body)
					  .addHeader("REQUEST-ID", uuidAsStringnotify11)
					  .addHeader("TIMESTAMP", formattedTime)
					  .addHeader("X-CM-ID", abdmCredentialdDtoswer.getXcmId())
					  .addHeader("Content-Type", "application/json")
					  .build();
					okhttp3.Response response = client.newCall(request).execute();
			
			JSONObject jsonObject1 = new JSONObject(response.body().string());
			String accessToken = jsonObject1.getString("accessToken");
			abdmCredentialdDtoswer.setAccessToken(accessToken);

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDtoswer);

		} catch (Exception e) {
		throw new ApplicationException(e.getMessage(), e);
	}

	}

