	@Override
	@Transactional
	public Response addUpdateServicesInAbdm(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {

			Response refsvv = getCredentialDetails(abdmCredentialdDto);
			if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();

				List alise = new ArrayList<>();
				alise.add(abdmCredentialdDto.getAliseName());

				JSONArray jsonArray1 = new JSONArray();
				JSONObject jsonObjectseond = new JSONObject();
				jsonObjectseond.put("id", abdmCredentialdDto.getName() + abdmCredentialdDto.getOrganizationId());
				jsonObjectseond.put("name", abdmCredentialdDto.getName());
				jsonObjectseond.put("type", "HIP");
				jsonObjectseond.put("active", "true");
				jsonObjectseond.put("alias", alise);
				jsonArray1.put(jsonObjectseond);
				String requestJson1 = jsonArray1.toString();

				OkHttpClient client = new OkHttpClient().newBuilder().build();
				MediaType mediaType = MediaType.parse("application/json");
				RequestBody body = RequestBody.create(mediaType, jsonObjectseond.toString());
				Request request = new Request.Builder().url(AsdbdmCredentialdDto.getDevUrl() + "/v1/bridges/services")
						.method("PUT", body).addHeader("Content-Type", "application/json")
						.addHeader("Accept", "application/json")
						.addHeader("Authorization", "Bearer " + accessToken + " ").build();
				okhttp3.Response response = client.newCall(request).execute();

				if (response.code() == 200) {

					Response finalResponse = addGetServiceAbdm(abdmCredentialdDto);

				} else {
					return new Response(ERROR, ERROR_CODE, response.message(), null, NULL);
				}
			}

			return new Response(SUCCESS, SUCCESS_CODE, null, null, NULL);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

	@Override
	@Transactional
	public Response generateOtpAadhar(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		// TODO Auto-generated method stub
		try {
			String txnId = "";
			Response refsvv = getCredentialDetails(abdmCredentialdDto);

			if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();

				JSONArray jsonArray1 = new JSONArray();
				JSONObject jsonObjectseond = new JSONObject();
				jsonObjectseond.put("aadhaar", abdmCredentialdDto.getAadharNumber());
				jsonArray1.put(jsonObjectseond);
				String requestJson1 = jsonArray1.toString().replaceAll("[\\[\\]]", "");

				System.out.println("/generateOtp  request" + requestJson1);
				OkHttpClient client = new OkHttpClient().newBuilder().build();
				MediaType mediaType = MediaType.parse("application/json");
				RequestBody body = RequestBody.create(mediaType, requestJson1);
				Request request = new Request.Builder()
						.url(AsdbdmCredentialdDto.getHealthidsbxUrl() + "/v1/registration/aadhaar/generateOtp")
						.method("POST", body).addHeader("accept", "*/*").addHeader("Accept-Language", "en-US")
						.addHeader("Content-Type", "application/json")
						.addHeader("Authorization", "Bearer " + accessToken + " ").build();
				okhttp3.Response response = client.newCall(request).execute();
				if (response.code() != 200) {
					return new Response(ERROR, ERROR_CODE, response.message(), null, NULL);
				}
				JSONObject jsonObject1 = new JSONObject(response.body().string());
				txnId = jsonObject1.getString("txnId");
				System.out.println("/generateOtp  response" + jsonObject1);
				System.out.println(txnId);
				abdmCredentialdDto.setTransactionId(txnId);

				AbdmTransaction at = new AbdmTransaction();
				at.setAadharNumber(abdmCredentialdDto.getAadharNumber());
				at.setTransactionId(abdmCredentialdDto.getTransactionId());
				at.setOrganizationId(abdmCredentialdDto.getOrganizationId());
				at.setUnitId(abdmCredentialdDto.getUnitId());
				at.setConsentChecked('Y');
				at.setUserId(abdmCredentialdDto.getUserId());
				sessionFactory.getCurrentSession().save(at);
			}
			return new Response(SUCCESS, SUCCESS_CODE, null, null, txnId);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

