	private static BufferedImage decodeToImage(byte[] bytes) {
		try {
			ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
			return ImageIO.read(bais);
		} catch (IOException e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

	private static String imageToBase64String(BufferedImage image) throws IOException {
		ByteArrayOutputStream baos = new ByteArrayOutputStream();
		ImageIO.write(image, "png", baos);
		byte[] imageBytes = baos.toByteArray();
		return Base64.getEncoder().encodeToString(imageBytes);
	}

	@Override
	@Transactional
	public Response fetchModesValidation(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		try {

			UUID uuid = UUID.randomUUID();
			String uuidAsString = uuid.toString();

			Response refsvv = getCredentialDetails(abdmCredentialdDto);
			if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();
				if (abdmCredentialdDto.getAadharNumber() != null) {
					Response profileDetailsResponse = getProfileDetailsByAdharNumber(abdmCredentialdDto);
					AbdmCredentialdDto profileAsdbdmCredentialdDto = (AbdmCredentialdDto) profileDetailsResponse
							.getObject();

					Instant currentTime = Instant.now();
					DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
					String formattedTime = currentTime.atZone(java.time.ZoneOffset.UTC).format(formatter);

					JSONArray jsonArray1 = new JSONArray();
					JSONObject jsonObjectseond = new JSONObject();
					JSONObject jsonObject = new JSONObject();
					JSONObject queryObject = new JSONObject();
					JSONObject requesterObject = new JSONObject();

					requesterObject.put("type", "HIP");
					requesterObject.put("id", AsdbdmCredentialdDto.getId());

					queryObject.put("id", abdmCredentialdDto.getSbxId());
					queryObject.put("purpose", "KYC_AND_LINK");
					queryObject.put("requester", requesterObject);

					// Populate the main JSON object
					jsonObject.put("requestId", uuidAsString);
					jsonObject.put("timestamp", formattedTime);
					jsonObject.put("query", queryObject);

					jsonArray1.put(jsonObject);
					String requestJson = jsonArray1.toString().replaceAll("[\\[\\]]", "");

					OkHttpClient client = new OkHttpClient().newBuilder().build();
					MediaType mediaType = MediaType.parse("application/json");
					RequestBody body = RequestBody.create(mediaType, requestJson);
					Request request = new Request.Builder()
							.url(profileAsdbdmCredentialdDto.getGatewayUrl() + "/v0.5/users/auth/fetch-modes")
							.method("POST", body).addHeader("Authorization", "Bearer " + accessToken)
							.addHeader("X-CM-ID", AsdbdmCredentialdDto.getXcmId())
							.addHeader("Content-Type", "application/json").build();
					okhttp3.Response responsefetchNew = client.newCall(request).execute();

					AbdmCallBackResponse abdmCallBackResponsenew = new AbdmCallBackResponse();
					abdmCallBackResponsenew.setRequestId(uuidAsString);
					abdmCallBackResponsenew.setHipId(AsdbdmCredentialdDto.getId());
					abdmCallBackResponsenew.setOrganizationId(abdmCredentialdDto.getOrganizationId());
					abdmCallBackResponsenew.setUnitId(abdmCredentialdDto.getUnitId());
					abdmCallBackResponsenew.setAadharNumber(abdmCredentialdDto.getAadharNumber());
					abdmCallBackResponsenew.setSbxId(abdmCredentialdDto.getSbxId());
					sessionFactory.getCurrentSession().save(abdmCallBackResponsenew);

					if (responsefetchNew.code() == 202) {
						return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCallBackResponsenew);
					} else if (responsefetchNew.code() == 2429) {
						return new Response(SUCCESS, SUCCESS_CODE, "Too many requests found", null, abdmCredentialdDto);
					} else {
						return new Response(ERROR, ERROR_CODE, responsefetchNew.message(), null, NULL);
					}
				}
			}

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDto);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

