	@Transactional
	private Response getCallBackTranscationIdForConfirmCall(AbdmCredentialdDto abdmCredentialdDto) throws Exception {
		try {

			AbdmCredentialdDto nbdmCredentialdDto = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery("select ddcds.call_back_json_on_init as \"callBackJsonoNOnInit\" "
							+ " from  abdm.m_call_back_response ddcds " + " WHERE ddcds.request_id =:requestId ")
					.setString("requestId", abdmCredentialdDto.getRequestId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();

			AbdmCredentialdDto abdmCredentialdDtoNew = new AbdmCredentialdDto();
			ObjectMapper objectMapper = new ObjectMapper();

			JsonNode jsonNode = objectMapper.readTree(nbdmCredentialdDto.getCallBackJsonoNOnInit());
			String transactionId = jsonNode.path("auth").path("transactionId").asText();
			AbdmCredentialdDto abdmCredentialdDtoTest = new AbdmCredentialdDto();
			abdmCredentialdDtoTest.setTransactionId(transactionId);

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDtoTest);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

	@Override
	@Transactional
	public Response getProfileDetailsByAdharNumber(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {

			AbdmCredentialdDto nbdmCredentialdDto = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery("select ddcds.aadhar_preverified_json as \"aadharPreverifiedJson\","
							+ " abdmcred.id as \"id\" " + " from abdm.m_abdm_transaction ddcds "
							+ " inner join abdm.m_abdm_credential abdmcred on " + " abdmcred.unit_id = ddcds.unit_id "
							+ " where ddcds.organization_id =:organizationId" + " and ddcds.unit_id =:unitId "
							+ " and ddcds.aadhar_number =:aadharNumber order by 1 desc limit 1 ")
					.setInteger("unitId", abdmCredentialdDto.getUnitId())
					.setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
					.setString("aadharNumber", abdmCredentialdDto.getAadharNumber())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();

			AbdmCredentialdDto abdmCredentialdDtoNew = new AbdmCredentialdDto();
			ObjectMapper objectMapper = new ObjectMapper();

			JsonNode jsonNode = objectMapper.readTree(nbdmCredentialdDto.getAadharPreverifiedJson());
			String fullName = jsonNode.get("name").asText();
			String firstName = jsonNode.get("firstName").asText();
			String middleName = jsonNode.get("middleName").asText();
			String lastName = jsonNode.get("lastName").asText();
			String pincode = jsonNode.get("pincode").asText();
			int districtCode = jsonNode.get("districtCode").asInt();
			String gender = jsonNode.get("gender").asText();
			String districtName = jsonNode.get("districtName").asText();
			String mobile = jsonNode.get("mobile").asText();
			String healthId = jsonNode.get("healthId").asText();
			String yearOfBirth = jsonNode.get("yearOfBirth").asText();
			String monthOfBirth = jsonNode.get("monthOfBirth").asText();
			String dayOfBirth = jsonNode.get("dayOfBirth").asText();
			String healthIdNumber = jsonNode.get("healthIdNumber").asText();
			String token = jsonNode.get("token").asText();
			String stateName = jsonNode.get("stateName").asText();
			String stateCode = jsonNode.get("stateCode").asText();
			String email = jsonNode.get("email").asText();
			String refreshToken = jsonNode.get("refreshToken").asText();

			abdmCredentialdDtoNew.setFullName(fullName);
			abdmCredentialdDtoNew.setFirstName(firstName);
			abdmCredentialdDtoNew.setMiddleName(middleName);
			abdmCredentialdDtoNew.setLastName(lastName);
			abdmCredentialdDtoNew.setPincode(pincode);
			abdmCredentialdDtoNew.setDistrictCode(districtCode);
			abdmCredentialdDtoNew.setBirthDate(yearOfBirth + "-" + monthOfBirth + "-" + dayOfBirth + " 00:00:00.000");
			abdmCredentialdDtoNew.setGender(gender);
			abdmCredentialdDtoNew.setDistrictName(districtName);
			abdmCredentialdDtoNew.setMobile(mobile);
			abdmCredentialdDtoNew.setHealthId(healthId);
			abdmCredentialdDtoNew.setId(nbdmCredentialdDto.getId());
			abdmCredentialdDtoNew.setHealthIdNumber(healthIdNumber);
			abdmCredentialdDtoNew.setToken(token);
			abdmCredentialdDtoNew.setStateName(stateName);
			abdmCredentialdDtoNew.setStateCode(stateCode);
			abdmCredentialdDtoNew.setEmail(email);
			abdmCredentialdDtoNew.setRefreshToken(refreshToken);
			abdmCredentialdDtoNew.setDayOfBirth(dayOfBirth);
			abdmCredentialdDtoNew.setMonthOfBirth(monthOfBirth);
			abdmCredentialdDtoNew.setYearOfBirth(yearOfBirth);

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDtoNew);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

