	@Override
	@Transactional
	public Response updateOnInitCall(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		try {
			try {

				ObjectMapper objectMapper = new ObjectMapper();
				JsonNode jsonNode = objectMapper.readTree(abdmCredentialdDto.getCallBackJsonoNOnInit());
				Integer code = jsonNode.path("error").path("code").asInt();
				if (code == 1511) {
					String message = jsonNode.path("message").asText();
					return new Response(SUCCESS, SUCCESS_CODE, message, null, abdmCredentialdDto);
				}

				Session session = sessionFactory.openSession();
				String query = "UPDATE AbdmCallBackResponse " + " SET callBackJsonoNOnInit = :callBackJsonoNOnInit "
						+ " WHERE requestIdInit=:responseRequestId";
				sessionFactory.getCurrentSession().createQuery(query)
						.setString("callBackJsonoNOnInit", abdmCredentialdDto.getCallBackJsonoNOnInit())
						.setString("responseRequestId", abdmCredentialdDto.getRequestIdInit()).executeUpdate();

				return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDto);

			} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

	@Override
	@Transactional
	public Response savePatientRegistrationFromABDMinHIS(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
			Response resp = getProfileDetailsByAdharNumber(abdmCredentialdDto);
			AbdmCredentialdDto profileAsdbdmCredentialdDto = (AbdmCredentialdDto) resp.getObject();
			Integer genderId = 1;
			if (profileAsdbdmCredentialdDto.getGender().equals("M")) {
				genderId = 1;
			} else if (profileAsdbdmCredentialdDto.getGender().equals("F")) {
				genderId = 2;
			}

			Integer prefixId = (Integer) sessionFactory.getCurrentSession()
					.createSQLQuery("select " + " prefix_id  " + " from " + " 	m_prefix_master mpm " + " where "
							+ " 	gender_id = " + genderId + " 	and organization_id ="
							+ abdmCredentialdDto.getOrganizationId() + " 	order by 1 desc limit 1 ")
					.uniqueResult();

			PatientRegistrationDto patientRegistrationDto = new PatientRegistrationDto();
			patientRegistrationDto.setAddress(profileAsdbdmCredentialdDto.getDistrictName());
			patientRegistrationDto.setMobileNumber(profileAsdbdmCredentialdDto.getMobile());
			patientRegistrationDto.setArea(null);
			patientRegistrationDto.setAreaName(null);
			patientRegistrationDto.setBirthDate(profileAsdbdmCredentialdDto.getBirthDate());
			patientRegistrationDto.setCityName(null);
			patientRegistrationDto.setCreatedBy(1);
			patientRegistrationDto.setCreatedDate(new Date().toString());
			patientRegistrationDto.setDob(
					profileAsdbdmCredentialdDto.getDayOfBirth() + "-" + profileAsdbdmCredentialdDto.getMonthOfBirth()
							+ "-" + profileAsdbdmCredentialdDto.getYearOfBirth() + " 00:00:00.000");
			patientRegistrationDto.setEmail(profileAsdbdmCredentialdDto.getEmail());
			patientRegistrationDto.setFirstName(profileAsdbdmCredentialdDto.getFirstName());
			patientRegistrationDto.setHealthId(profileAsdbdmCredentialdDto.getHealthId());
			patientRegistrationDto.setHealthNumber(profileAsdbdmCredentialdDto.getHealthIdNumber());
			patientRegistrationDto.setLastName(profileAsdbdmCredentialdDto.getLastName());
			patientRegistrationDto.setMiddleName(profileAsdbdmCredentialdDto.getMiddleName());
			patientRegistrationDto.setOrganizationId(abdmCredentialdDto.getOrganizationId());
			patientRegistrationDto.setPermanentAddress(profileAsdbdmCredentialdDto.getDistrictName());
			patientRegistrationDto.setStateName(profileAsdbdmCredentialdDto.getStateName());
			patientRegistrationDto.setUnitId(abdmCredentialdDto.getUnitId());
			patientRegistrationDto.setOrganizationId(abdmCredentialdDto.getOrganizationId());
			patientRegistrationDto.setUpdatedBy(abdmCredentialdDto.getUserId());
			patientRegistrationDto.setVisitTypeId(1);
			patientRegistrationDto.setWhatsappNo(profileAsdbdmCredentialdDto.getMobile());
			patientRegistrationDto.setZipCode(profileAsdbdmCredentialdDto.getPincode());
			patientRegistrationDto.setRegistrationTypeId(1);
			patientRegistrationDto.setGenderId(genderId);
			patientRegistrationDto.setCreatedDate(GlobalCommonDateUtils.getStringDate(
					TimeZoneComponent.getDateByzone(abdmCredentialdDto.getUnitId()), "dd-MM-yyyy HH:mm:ssss"));
			patientRegistrationDto.setUpdatedDate(GlobalCommonDateUtils.getStringDate(
					TimeZoneComponent.getDateByzone(abdmCredentialdDto.getUnitId()), "dd-MM-yyyy HH:mm:ssss"));
			patientRegistrationDto.setPrefixId(prefixId);
			patientRegistrationDto.setAadharNumber(profileAsdbdmCredentialdDto.getAadharNumber());
			patientRegistrationDto.setHealthId(profileAsdbdmCredentialdDto.getHealthId());
			patientRegistrationDto.setHealthNumber(profileAsdbdmCredentialdDto.getHealthIdNumber());
			Response respd = iPatientRegistrationService.registerPatient(patientRegistrationDto);
			Integer patientId = (Integer) respd.getObject();
			patientRegistrationDto.setPatientId(patientId);
			return new Response(SUCCESS, SUCCESS_CODE, null, null, patientId);
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
		// return null;

	}

