	@Override
	@Transactional
	public Response getProfileDetailsByCallBackURLResponse(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {

			AbdmCredentialdDto dto = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery(
							"select " + " mac.organization_id as \"organizationId\", " + " mac.unit_id as \"unitId\" "
									+ " from abdm.m_abdm_credential mac " + " where mac.id =:id")
					.setString("id", abdmCredentialdDto.getHipId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();
			abdmCredentialdDto.setUnitId(dto.getUnitId());
			abdmCredentialdDto.setOrganizationId(dto.getOrganizationId());

			ObjectMapper objectMapper = new ObjectMapper();
			JsonNode jsonNode = objectMapper.readTree(abdmCredentialdDto.getCallBackJsonoNOnConfirm());
			String healthId = jsonNode.path("auth").path("patient").path("id").asText();
			String fullName = jsonNode.path("auth").path("patient").path("name").asText();
			String gender = jsonNode.path("auth").path("patient").path("gender").asText();
			String yearOfBirth = jsonNode.path("auth").path("patient").path("yearOfBirth").asText();
			String monthOfBirth = jsonNode.path("auth").path("patient").path("monthOfBirth").asText();
			String dayOfBirth = jsonNode.path("auth").path("patient").path("dayOfBirth").asText();
			String[] h = fullName.split(" ");
			String firstName = h[0];
			String middleName = h[1];
			String lastName = h[2];
			String pincode = jsonNode.path("auth").path("patient").path("address").path("pincode").asText();
			String districtName = jsonNode.path("auth").path("patient").path("address").path("district").asText();
			String stateName = jsonNode.path("auth").path("patient").path("address").path("state").asText();

			JSONObject jsonObject = new JSONObject(abdmCredentialdDto.getCallBackJsonoNOnConfirm());
			JSONObject auth = jsonObject.getJSONObject("auth");
			JSONObject patient = auth.getJSONObject("patient");
			JSONArray identifiers = patient.getJSONArray("identifiers");
			String mobile = null;
			String healthIdNumber = null;

			for (int i = 0; i < identifiers.length(); i++) {
				JSONObject identifier = identifiers.getJSONObject(i);
				String type = identifier.getString("type");
				if (type.equalsIgnoreCase("MOBILE")) {
					mobile = identifier.getString("value");
				}
				if (type.equalsIgnoreCase("HEALTH_NUMBER")) {
					healthIdNumber = identifier.getString("value");
				}

			}

			abdmCredentialdDto.setFullName(fullName);
			abdmCredentialdDto.setFirstName(firstName);
			abdmCredentialdDto.setMiddleName(middleName);
			abdmCredentialdDto.setLastName(lastName);
			abdmCredentialdDto.setPincode(pincode);
			abdmCredentialdDto.setBirthDate(yearOfBirth + "-" + monthOfBirth + "-" + dayOfBirth + " 00:00:00.000");
			abdmCredentialdDto.setGender(gender);
			abdmCredentialdDto.setDistrictName(districtName);
			abdmCredentialdDto.setMobile(mobile);
			abdmCredentialdDto.setHealthId(healthId);
			abdmCredentialdDto.setId(abdmCredentialdDto.getHipId());
			abdmCredentialdDto.setHealthIdNumber(healthIdNumber);
			abdmCredentialdDto.setStateName(stateName);
			abdmCredentialdDto.setDayOfBirth(dayOfBirth);
			abdmCredentialdDto.setMonthOfBirth(monthOfBirth);
			abdmCredentialdDto.setYearOfBirth(yearOfBirth);

			Response abdmCredentialdDtosssssss = checkPatientAlreadyExist(abdmCredentialdDto);
			AbdmCredentialdDto profileAsdbdmCredentialdDto = (AbdmCredentialdDto) abdmCredentialdDtosssssss.getObject();

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDto);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

