	@Override
	@Transactional
	public Response saveDiscoverResponse(AbdmCredentialdDto ab) throws ApplicationException, Exception {
		try {

			AbdmCredentialdDto abdmCredentialdDtoNew = new AbdmCredentialdDto();
			ObjectMapper objectMapper = new ObjectMapper();

			JsonNode jsonNode = objectMapper.readTree(ab.getDiscoverJson());
			String healthId = jsonNode.path("patient").path("id").asText();
			String requestId = jsonNode.path("requestId").asText();
			String transactionId = jsonNode.path("transactionId").asText();

			abdmCredentialdDtoNew.setHealthId(healthId);
			abdmCredentialdDtoNew.setDiscoverJson(ab.getDiscoverJson());
			abdmCredentialdDtoNew.setRequestId(requestId);
			abdmCredentialdDtoNew.setTransactionId(transactionId);

			AbdmDiscoverResponse abdmDiscoverResponse = new AbdmDiscoverResponse();
			abdmDiscoverResponse.setDiscoverJson(ab.getDiscoverJson());
			abdmDiscoverResponse.setHipId(ab.getHipId());
			abdmDiscoverResponse.setRequestId(requestId);
			abdmDiscoverResponse.setSbxId(healthId);
			abdmDiscoverResponse.setTransactionId(transactionId);
			sessionFactory.getCurrentSession().save(abdmDiscoverResponse);

			onDiscoverMode(abdmCredentialdDtoNew);

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDtoNew);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

