	@Override
	public Response getCard(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		try {

			Response refsvv = getCredentialDetails(abdmCredentialdDto);
			if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();

				OkHttpClient client = new OkHttpClient().newBuilder().build();
				Response masterRes = util.getAbdmUrlDetails(abdmCredentialdDto);
				AbdmCredentialdDto master = (AbdmCredentialdDto) masterRes.getObject();

				String url = master.getBaseUrl() + master.getBasePath() + master.getApiUrl();

				Request request = new Request.Builder().url(url).method("GET", null).addHeader("accept", "*/*")
						.addHeader("Accept-Language", "en-US").addHeader("Authorization", "Bearer " + accessToken + " ")
						.addHeader("X-token", "Bearer " + abdmCredentialdDto.getToken() + " ").build();
				try {
					okhttp3.Response response = client.newCall(request).execute();
					if (response.code() == 202) {
						byte[] rawImageData = response.body().bytes();
						String base64Image = Base64.getEncoder().encodeToString(rawImageData);
						abdmCredentialdDto.setBase64PngCard(base64Image);
						return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDto);
					} else {
						return new Response(ERROR, String.valueOf(response.code()), response.message(), null, null);
					}

				} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
			}

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
		return null;
	}

