	@Override
	@Transactional
	public Response v3TokenGenerateToken(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		try {
			UUID uuid = UUID.randomUUID();
			String uuidString = uuid.toString();
			Instant currentTime = Instant.now();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
			String formattedTime = currentTime.atZone(java.time.ZoneOffset.UTC).format(formatter);
			abdmCredentialdDto.setEventId(abdmCredentialdDto.getEventId());
			Response masterRes = util.getAbdmUrlDetails(abdmCredentialdDto);
			AbdmCredentialdDto master = (AbdmCredentialdDto) masterRes.getObject();

			String url = master.getBaseUrl() + master.getBasePath() + master.getApiUrl();
			Response refsvv = getCredentialDetails(abdmCredentialdDto);
			if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();

				// Create the root JSON object
				JSONObject jsonObject = new JSONObject();

				// Add the abhaNumber
				jsonObject.put("abhaNumber", abdmCredentialdDto.getAbhaNumber()); // Note
																					// the
																					// 'L'
																					// to
																					// specify
																					// a
																					// long
																					// number

				// Add the abhaAddress
				jsonObject.put("abhaAddress", abdmCredentialdDto.getHealthId());

				// Add the name
				jsonObject.put("name", abdmCredentialdDto.getName());

				// Add the gender
				jsonObject.put("gender", abdmCredentialdDto.getGender());

				// Add the yearOfBirth
				jsonObject.put("yearOfBirth", abdmCredentialdDto.getYearOfBirth());

				// Print the JSON object
				// System.out.println(jsonObject.toString(4));

				OkHttpClient client = new OkHttpClient().newBuilder().build();
				MediaType mediaType = MediaType.parse("application/json");
				RequestBody body = RequestBody.create(mediaType, jsonObject.toString());
				Request request = new Request.Builder().url(url).method("POST", body)
						.addHeader("X-HIP-ID", AsdbdmCredentialdDto.getId())
						.addHeader("X-CM-ID", AsdbdmCredentialdDto.getXcmId())
						.addHeader("Content-Type", "application/json")
						.addHeader("Authorization", "Bearer " + accessToken + " ").addHeader("REQUEST-ID", uuidString)
						.addHeader("TIMESTAMP", formattedTime).build();

				try {

					okhttp3.Response response = client.newCall(request).execute();

					if (response.code() == 202) {
						String resBOdy = response.body().toString();
						System.out.println("generate token response" + resBOdy);
						abdmCredentialdDto.setTransactionId(uuidString);
						AbdmTransaction at = new AbdmTransaction();
						at.setTransactionId(uuidString);
						at.setOrganizationId(abdmCredentialdDto.getOrganizationId());
						at.setUnitId(abdmCredentialdDto.getUnitId());
						at.setConsentChecked('Y');
						at.setUserId(abdmCredentialdDto.getUserId());
						at.setApiResponseEvent28(jsonObject.toString());
						at.setApiResponses(response.body().toString());
						sessionFactory.getCurrentSession().save(at);
						return new Response(SUCCESS, String.valueOf(response.code()), "Accepted", null,
								abdmCredentialdDto);
					} else {
						String resBOdy = response.body().toString();
						System.out.println("generate token response" + resBOdy);
						return new Response(ERROR, String.valueOf(response.code()), "Please try again after 10 mins",
								null, null);
					}
				} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
			}
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

		return new Response(ERROR, ERROR_CODE, "Connection timeout", null, null);

	}

