				if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
					AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
					accessToken = AsdbdmCredentialdDto.getAccessToken();
				}

				String url = master.getBaseUrl() + master.getBasePath() + master.getApiUrl();

				ObjectMapper objectMapper = new ObjectMapper();
				JsonNode jsonNode = objectMapper.readTree(abdmCredentialdDto.getDiscoverJson());
				String healthId = jsonNode.path("patient").path("id").asText();
				String yearOfBirth = jsonNode.path("patient").path("yearOfBirth").asText();
				String patientName = jsonNode.path("patient").path("name").asText();
				String patientGender = jsonNode.path("patient").path("gender").asText();
				String transactionId = jsonNode.path("transactionId").asText();
				String errorMessage = jsonNode.path("error").path("message").asText();
				String gender = jsonNode.path("patient").path("gender").asText();
				JsonNode verifiedIdentifiersArray = jsonNode.path("patient").path("verifiedIdentifiers");

				String[] nameParts = patientName.split(" ");

				String patientFirstName = nameParts[0];
				// System.out.println(patientFirstName);
				String patientMiddleName = nameParts[1];
				// System.out.println(patientMiddleName);
				String patientLastName = nameParts[2];
