	@Transactional
    private String getEncodedStringOfFhIR(String dataPushUrl, String resourceBundle, String keyValue,
			String nonce, String transactionId, String cryptoAlg, String expiry, String curve, String parameters,
			Integer index, Integer pageNumber, String encounterNumber) {
    	try {
			String patientData = null;
			EncryptionRequest encryptionRequest = new EncryptionRequest(keyValue, nonce, privateKey, publicKey, nounce,
					resourceBundle);
			EncryptionResponse encryptedData = null;
			EncryptionController encryptionController = new EncryptionController();
			encryptedData = encryptionController.encrypt(encryptionRequest);
			return encryptedData.getEncryptedData();
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

