	private okhttp3.Response transferDataNotifyCall(String consentId, String transactionId,
			AbdmCredentialdDto abdmCredentialdDto, String encounterNumber, String accessToken,
			AbdmCredentialdDto AsdbdmCredentialdDto) {

		try {

			UUID uuidnotify = UUID.randomUUID();
			String uuidAsStringnotify = uuidnotify.toString();
			Instant currentTimenotify = Instant.now();
			DateTimeFormatter formatternotify = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
			String formattedTimenotify = currentTimenotify.atZone(java.time.ZoneOffset.UTC).format(formatternotify);
			JSONObject root = new JSONObject();
			JSONObject notification = new JSONObject();
			notification.put("consentId", consentId);
			notification.put("transactionId", transactionId);
			notification.put("doneAt", formattedTimenotify);
			JSONObject notifier = new JSONObject();
			notifier.put("type", "HIP");
			notifier.put("id", abdmCredentialdDto.getHipId());
			notification.put("notifier", notifier);
			JSONObject statusNotification = new JSONObject();
			statusNotification.put("sessionStatus", "TRANSFERRED");
			statusNotification.put("hipId", abdmCredentialdDto.getHipId());
			JSONArray statusResponses = new JSONArray();
			JSONObject statusResponse = new JSONObject();
			statusResponse.put("careContextReference", encounterNumber);
			statusResponse.put("hiStatus", "DELIVERED");
			statusResponse.put("description", "test care context");
			statusResponses.put(statusResponse);
			statusNotification.put("statusResponses", statusResponses);
			notification.put("statusNotification", statusNotification);
			root.put("notification", notification);
			// System.out.println(root.toString(4));
			abdmCredentialdDto.setEventId(38);
			Response masterRes1 = util.getAbdmUrlDetails(abdmCredentialdDto);
			AbdmCredentialdDto master1 = (AbdmCredentialdDto) masterRes1.getObject();

			String url1 = master1.getBaseUrl() + master1.getBasePath() + master1.getApiUrl();
			// Thread.sleep(1000);
			OkHttpClient clientNotify = new OkHttpClient().newBuilder().build();
			MediaType mediaTypeNotify = MediaType.parse("application/json");
			RequestBody bodyNotify = RequestBody.create(mediaTypeNotify, root.toString());
			Request requestNotify = new Request.Builder().url(url1).method("POST", bodyNotify)
					.addHeader("REQUEST-ID", uuidAsStringnotify).addHeader("TIMESTAMP", formattedTimenotify)
					.addHeader("X-CM-ID", AsdbdmCredentialdDto.getXcmId()).addHeader("Content-Type", "application/json")
					.addHeader("Authorization", "Bearer " + accessToken + " ").build();
			try {
				okhttp3.Response responseNotify = clientNotify.newCall(requestNotify).execute();
				if (responseNotify.code() == 202) {
					// System.out.println("sucesss notify call");
					String resBOdy = responseNotify.body().toString();
					return responseNotify;
				} else {
					// System.out.println("fails notify call");
					return responseNotify;
				}
			} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
		} catch (Exception ex) {
			logger.error(ex.getMessage(), ex);
			throw new ServiceException(ex.getMessage());
		}
	}

	private okhttp3.Response datapushURLPostData(String dataPushUrl, String resourceBundle, String keyValue,
			String nonce, String transactionId, String cryptoAlg, String expiry, String curve, String parameters,
			Integer index, Integer pageNumber, String encounterNumber) {
		try {
			// FHIR CODE FINAL
			String patientData = null;
			// KeyMaterial keyMaterial = keysController.generate({�);
			EncryptionRequest encryptionRequest = new EncryptionRequest(keyValue, nonce, privateKey, publicKey, nounce,
					resourceBundle);

			// encryption logic
			EncryptionResponse encryptedData = null;
			EncryptionController encryptionController = new EncryptionController();
			encryptedData = encryptionController.encrypt(encryptionRequest);

			System.out.println("transfer call datapushh: " + dataPushUrl);

			String transferJson = "{  \"pageNumber\":" + pageNumber + " , " + " \"pageCount\": " + pageNumber + " , "
					+ " \"transactionId\": \"" + transactionId + "\"," + "  \"entries\": [  " + " {"
					+ "     \"content\": \"" + encryptedData.getEncryptedData() + "\","
					+ "     \"media\": \"application/fhir+json\"," + "     \"checksum\": \"" + getMd5(resourceBundle)
					+ "\"," + "     \"careContextReference\": \"" + encounterNumber + "\" }" + " ],  "
					+ " \"keyMaterial\": {  " + "   \"cryptoAlg\": \"" + cryptoAlg + "\"," + "   \"curve\": \"" + curve
					+ "\"," + "     \"dhPublicKey\": {      " + "  \"expiry\": \"" + expiry + "\","
					+ "      \"parameters\":" + "  \"" + parameters + "\"," + "       \"keyValue\": \""
					+ encryptedData.getKeyToShare() + "\"    },  " + "   \"nonce\": \"" + nounce + "\" " + "  } " + "}";
			System.out.println("transfer json " + transferJson);
			OkHttpClient clientTran = new OkHttpClient().newBuilder().build();
			MediaType mediaTypeTran = MediaType.parse("application/json");
			RequestBody bodyTran = RequestBody.create(mediaTypeTran, transferJson);
			Request requestTran = new Request.Builder().url(dataPushUrl).method("POST", bodyTran)
					.addHeader("Content-Type", "application/json").build();
			okhttp3.Response responseTran = clientTran.newCall(requestTran).execute();
			System.out.println("transfer data Code " + responseTran.code());
			String responseBody = responseTran.body().string();
			System.out.println("Response Body is: " + responseBody);
			return responseTran;
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

	private boolean isMatchingMedication(MedicationDTO medicationDTO1, MedicationDTO medicationDTO2) {
		return medicationDTO1.getItemName().equals(medicationDTO2.getItemName())
				&& medicationDTO1.getGenericName().equals(medicationDTO2.getGenericName())
				&& medicationDTO1.getStartDate().equals(medicationDTO2.getStartDate())
				&& medicationDTO1.getEndDate().equals(medicationDTO2.getEndDate())
				&& medicationDTO1.getFrequencyDesc().equals(medicationDTO2.getFrequencyDesc());
	}

	private boolean isMatchingProcedure(ProcedureOrderMasterDto procedureDTO1, ProcedureOrderMasterDto procedureDTO2) {
		return procedureDTO1.getProcedureName().equals(procedureDTO2.getProcedureName())
				&& procedureDTO1.getPreferedDateTime().equals(procedureDTO2.getPreferedDateTime());
	}

	private boolean isMatchinglabOrder(InvestigationOrderMasterNewDto labOrderDTO1,
			InvestigationOrderMasterNewDto labOrderDTO2) {
		return labOrderDTO1.getServiceStandardName().equals(labOrderDTO2.getServiceStandardName());
	}

