			HealthDocumentRecord.put("entry", entryArray);

			// Setting signature
			JSONObject signature = new JSONObject();
			JSONArray typeArray = new JSONArray();
			JSONObject typeObj = new JSONObject();
			typeObj.put("system", "urn:iso-astm:E1762-95:2013");
