			signature.put("who", who);

			signature.put("sigFormat", "image/jpeg");
			signature.put("data",
					"");

			HealthDocumentRecord.put("signature", signature);

			// Printing the JSONObject to check
			// System.out.println(HealthDocumentRecord.toString(4));

			return HealthDocumentRecord.toString();
