	private static String sendReportRequest(String API_URL, String reportParam) {

		CloseableHttpClient httpClient = HttpClients.createDefault();
		HttpPost post = new HttpPost(API_URL);
		post.addHeader("Content-Type", "application/json");

		try {
			post.setEntity(new StringEntity(reportParam));

			HttpResponse result = httpClient.execute(post);
			HttpEntity resEntity = result.getEntity();
			ByteArrayOutputStream byteOutPutStream = new ByteArrayOutputStream();
			resEntity.writeTo(byteOutPutStream);

			String b64 = Base64.getEncoder().encodeToString(byteOutPutStream.toByteArray());

			// Log or process base64-encoded output
			// System.out.println("Base64 encoded report: " + b64);

			byteOutPutStream.close();
			httpClient.close();
			return b64;
		} catch (UnsupportedEncodingException e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		} catch (IOException e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

