	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response getEncounterNumberByPatientId(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
			List<EncounterMasterDto> list1 = sessionFactory.getCurrentSession()
					.createSQLQuery(
							"select tem.encounter_number  as \"encounterNumber\",tem.encounter_id  as \"encounterId\",to_char(tem.encounter_date,'DD/MM/YYYY') as \"encounterDateString2\",to_char(tem.encounter_date,'DD/MM/YYYY HH24:MI:SS') as \"careContextTime\",  tem.patient_id as \"patientId\" "
									+ " from opd.t_encounter_master tem " + " where tem.patient_id =:patientId and "
									+ "tem.organization_id =:organizationId " + "and tem.unit_id =:unitId ")

					.setInteger("patientId", abdmCredentialdDto.getPatientId())
					.setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
					.setInteger("unitId", abdmCredentialdDto.getUnitId())
					.setResultTransformer(Transformers.aliasToBean(EncounterMasterDto.class)).list();
			return new Response(SUCCESS, null, null, list1, null);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response getAdmissionNumberByPatientId(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
			List<AbdmCredentialdDto> list1 = sessionFactory.getCurrentSession()
					.createSQLQuery(" select distinct (ta.admission_id) as \"admissionId\","
							+ " to_char(tad.doa,'DD/MM/YYYY') as \"encounterDateString2\", "
							+ " to_char(ta.created_date, 'DD/MM/YYYY HH24:MI:SS') as \"careContextTime\", "
							+ " ta.admission_number as \"admissionNumber\" " + " from adt.t_admission ta "
							+ " inner join adt.t_admission_details tad on " + " tad.admission_id =ta.admission_id "
							+ " where ta.patient_id =:patientId and " + "ta.organization_id =:organizationId "
							+ "and ta.unit_id =:unitId ")
					.setInteger("patientId", abdmCredentialdDto.getPatientId())
					.setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
					.setInteger("unitId", abdmCredentialdDto.getUnitId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).list();
			return new Response(SUCCESS, null, null, list1, null);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

