					String fromDate = dateRangeNode.path("from").asText();
					String toDate = dateRangeNode.path("to").asText();

					// Extract dataEraseAt
					String dataEraseAt = rootNode1.path("consent").path("consentDetail").path("permission")
							.path("dataEraseAt").asText();

					JsonNode hiTypesNode = rootNode1.path("consent").path("consentDetail").path("hiTypes");

