	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response v3ConsentRequestOnInit(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {

			ObjectMapper objectMapper = new ObjectMapper();
			JsonNode rootNode = objectMapper.readTree(abdmCredentialdDto.getOnInitJson());
			String id = rootNode.path("consentRequest").path("id").asText();
			String requestIdres = rootNode.path("response").path("requestId").asText();

			System.out.println("on care req id " + requestIdres);
			String query = "UPDATE ConsentRequestData "
					+ " SET apiResponseOninitRequest =:apiResponseOninitRequest, consentRequestIdHiu=:consentId "
					+ " WHERE requestId=:requestId";
			sessionFactory.getCurrentSession().createQuery(query).setString("requestId", requestIdres)
					.setString("consentId", id)// Consent REquest Id
					.setString("apiResponseOninitRequest", abdmCredentialdDto.getOnInitJson()).executeUpdate();

			return new Response(SUCCESS, "202", null, null, abdmCredentialdDto);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response v3ConsentRequestNotify(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
			String requestIds = abdmCredentialdDto.getRequestId();
			ObjectMapper objectMapper = new ObjectMapper();
			JsonNode rootNode = objectMapper.readTree(abdmCredentialdDto.getNotifyConsentJson());
			String consentArtificateId = null;
			String consentRequestId = rootNode.path("notification").path("consentRequestId").asText();
			String status = rootNode.path("notification").path("status").asText();
			JsonNode consentArtefactsNode = rootNode.path("notification").path("consentArtefacts");
			if (consentArtefactsNode.isArray()) {
				// Loop through the array elements
				for (JsonNode artefactNode : consentArtefactsNode) {
					consentArtificateId = artefactNode.path("id").asText();
					System.out.println("ID: " + consentArtificateId);
					abdmCredentialdDto.setConsentArtefactsId(consentArtificateId);
					abdmCredentialdDto.setConsentStatus(status);
					ConsentRequestArtifactId consentRequestArtifactId = new ConsentRequestArtifactId();
					consentRequestArtifactId.setConsentArtefactsId(consentArtificateId);
					consentRequestArtifactId.setConsentRequestId(consentRequestId);
					consentRequestArtifactId.setConsentId(consentArtificateId);
					sessionFactory.getCurrentSession().save(consentRequestArtifactId);
				}

				v3ConsentRequestHiuOnNotify(abdmCredentialdDto);

			} else {
				// Handle case where consentArtefactsNode is not an array or is
				// empty
				System.out.println("No consent artefacts found or consentArtefactsNode is not an array.");
			}

			if (status.equalsIgnoreCase("GRANTED")) {
				String query = "UPDATE ConsentRequestData "
						+ " SET consentGrantedDate =:consentGrantedDate,consentStatus =:status "
						+ " WHERE consentRequestIdHiu=:consentRequestIdHiu";
				sessionFactory.getCurrentSession().createQuery(query).setString("consentRequestIdHiu", consentRequestId)
						.setString("status", status).setString("consentGrantedDate", abdmCredentialdDto.getTimeStamp())
						.executeUpdate();

			} else if (status.equalsIgnoreCase("REVOKED")) {

				String query = "UPDATE ConsentRequestData "
						+ " SET consentRevokedDate =:consentRevokedDate ,consentStatus =:status"
						+ " WHERE consentRequestIdHiu=:consentRequestIdHiu";
				sessionFactory.getCurrentSession().createQuery(query).setString("consentRequestIdHiu", consentRequestId)
						.setString("status", status).setString("consentRevokedDate", abdmCredentialdDto.getTimeStamp())
						.executeUpdate();

			} else if (status.equalsIgnoreCase("DENIED")) {

				String query = "UPDATE ConsentRequestData "
						+ " SET consentDeniedDate =:consentDeniedDate ,consentStatus =:status"
						+ " WHERE consentRequestIdHiu=:consentRequestIdHiu";
				sessionFactory.getCurrentSession().createQuery(query).setString("consentRequestIdHiu", consentRequestId)
						.setString("status", status).setString("consentDeniedDate", abdmCredentialdDto.getTimeStamp())
						.executeUpdate();
			}

			return new Response(SUCCESS, "202", null, null, abdmCredentialdDto);

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response getConsentRequestDetails(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
		       
			String query = " " +
				    " SELECT " +
				    "   consent.hip_id AS \"hipId\", " +
				    "   consent.sbx_id AS \"sbxId\", " +
				    "   consent.abha_id AS \"abhaId\", " +
				    "   TO_CHAR(consent.created_date AT TIME ZONE 'Asia/Kolkata', 'DD-MM-YYYY HH24:MI:SS') AS \"createdDate\", " +
				    "   consent.consent_expiry_date AS \"consentExpiryDate\", " +
				    "   consent.hi_types AS \"hiTypesRequested\", " +
				    "   consent.consent_id AS \"consentId\", " +
				    "   CASE " +
				    "     WHEN TO_TIMESTAMP(consent.consent_expiry_date, 'DD-MM-YYYY, HH24:MI') <= CURRENT_TIMESTAMP THEN 'Expired' " +
				    "     ELSE consent.consent_status " +
				    "   END AS \"consentStatus\", " +
				    "   consent.consent_response_hitypes AS \"consentResponseHitypes\", " +
				    "   consent.consent_denied_date AS \"consentDeniedDate\", " +
				    "   consent.consent_revoked_date AS \"consentRevokedDate\", " +
				    "   consent.consent_granted_date AS \"consentGrantedDate\", " +
				    "   consent.consent_from_date AS \"consentFromDate\", " +
				    "   consent.consent_todate AS \"consentToDate\", " +
				    "   consent.consent_artefacts_id AS \"consentArtefactsId\", " +
				    "   consent.health_number AS \"healthNumber\", " +
				    "   consent.patient_name AS \"patientName\", " +
				    "   consent.patient_full_name AS \"patientFullName\", " +
				    "   consent.mobile_number AS \"mobileNumber\", " +
				    "   consent.consent_request_id_hiu AS \"consentRequestIdHiu\" " +
				    " FROM abdm.m_consent_request_data consent " +
				    "WHERE consent.organisation_id = :organizationId and consent.unit_id = :unitId "
				    +" ORDER BY consent.consent_request_id DESC";

		    	   List<AbdmCredentialdDto>   listConsentDetails = sessionFactory.getCurrentSession().createSQLQuery(query.toString())
		    			   .setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
		    			   .setInteger("unitId", abdmCredentialdDto.getUnitId())
							.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).list();
					
		    	   return new Response(SUCCESS, SUCCESS_CODE, null, listConsentDetails, null);
			  
	       }catch(Exception e)
	      {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
		       

		}

	

