	@org.springframework.transaction.annotation.Transactional
	private EncounterMasterDto fetchEncountersForDecryption(String encounterNumber) {
		EncounterMasterDto dto = new EncounterMasterDto();
		dto = (EncounterMasterDto) sessionFactory.getCurrentSession().createSQLQuery("select "
				+ "	encounter.encounter_id as \"encounterId\", " + "	encounter.dept_id as \"deptId\", "
				+ "	encounter.organization_id as \"organizationId\", " + "	encounter.patient_id as \"patientId\", "
				+ "	encounter.unit_id as \"unitId\", "
				+ "	encounter.user_defined_visit_type_id as \"userDefinedVisitTypeId\", "
				+ "	to_char(encounter.encounter_date, 'HH24:MI:SS') as \"visitTime\", "
				+ "	to_char(encounter.encounter_date, 'yyyy-mm-dd') as \"encounterDateString\", "
				+ "   to_char(encounter.encounter_date, 'DD/MM/YYYY HH24:MI:SS') as \"encounterDateString2\", "
				+ "   'OP' as \"visitTypeName\", " + "	encounter.encounter_number as \"encounterNumber\", "
				+ "	encounter.doctor_id as \"doctorId\", " + "   doc.signture_img as \"signtureImg\", "
				+ "	encounter.patient_class_id as \"patientClassId\", "
				+ "	('Dr. ' || coalesce(doc.first_name)|| ' ' || coalesce(doc.middle_name)|| ' ' || coalesce(doc.last_name)) as \"doctorName\", "
				+ "	encounter.dept_id as \"specialityId\", " + "	speciality.speciality_name as \"specialityName\" "
				+ "from " + "	opd.t_encounter_master encounter " + "inner join doctor.m_doctor_master doc on "
				+ "	encounter.doctor_id = doc.doctor_id " + "inner join doctor.m_speciality_master speciality on "
				+ "	encounter.dept_id = speciality.speciality_id " + "where " +
				// " encounter.organization_id = :organizationId " +
				" encounter.encounter_number = :number  " + " limit 5").setString("number", encounterNumber)
				.setResultTransformer(Transformers.aliasToBean(EncounterMasterDto.class)).uniqueResult();

		if (dto == null) {
			dto = (EncounterMasterDto) sessionFactory.getCurrentSession().createSQLQuery("select "
					+ "    admission.admission_id as \"admissionId\", " + "   admission.speciality_id as \"deptId\", " + // Placeholder
																															// for
																															// deptId
					"   admission.visit_type_id as \"userDefinedVisitTypeId\", " + // Placeholder
																					// for
																					// userDefinedVisitTypeId
					"   NULL as \"visitTime\", " + // Placeholder for visitTime
					"   to_char(admission.created_date, 'yyyy-mm-dd') as \"encounterDateString\", " + // Placeholder
																										// for
																										// encounterDateString
					"   to_char(admission.created_date, 'DD/MM/YYYY HH24:MI:SS') as \"encounterDateString2\", "
					+ "   admission.admission_number as \"encounterNumber\", "
					+ "	admission.organization_id as \"organizationId\", " + "	admission.unit_id as \"unitId\", "
					+ "   'IP' as \"visitTypeName\", " + "   admission.doctor_id as \"doctorId\", "
					+ "   doc.signture_img as \"signtureImg\", " + "   NULL as \"patientClassId\", " + // Placeholder
																										// for
																										// patientClassId
					"	('Dr. ' || coalesce(doc.first_name)|| ' ' || coalesce(doc.middle_name)|| ' ' || coalesce(doc.last_name)) as \"doctorName\", "
					+ "   NULL as \"specialityId\", " + // Placeholder for
														// specialityId
					"   NULL as \"specialityName\" " + // Placeholder for
														// specialityName
					"from " + "   adt.t_admission admission " + "inner join doctor.m_doctor_master doc on "
					+ "	admission.doctor_id = doc.doctor_id " + "where " + "    admission.admission_number = :number "
					+ " limit 5").setString("number", encounterNumber)
					.setResultTransformer(Transformers.aliasToBean(EncounterMasterDto.class)).uniqueResult();
		}

		return dto;
	}

	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response getHiuDecryptedData(AbdmCredentialdDto abdmCredentialdDto) throws ApplicationException, Exception {
		try {

			String query = " " + " select consent.consent_artefacts_id as \"consentArtefactsId\","
					+ " consent.transaction_id as \"transactionId\" "
					+ " from abdm.m_consent_request_artifact_id consent "
					+ " where consent.consent_request_id =:consentRequestIdHiu ";

			List<AbdmCredentialdDto> listconsentArtefactsIdList = sessionFactory.getCurrentSession()
					.createSQLQuery(query.toString())
					.setString("consentRequestIdHiu", abdmCredentialdDto.getConsentRequestIdHiu())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).list();

			List<AbdmCredentialdDto> listDecryptedDetailsNew = new ArrayList();

			for (AbdmCredentialdDto dto : listconsentArtefactsIdList) {
				String query1 = " select hiu.carecontex_reference as \"carecontexReference\", "
						+ " hiu.encounter_number as \"encounterNumber\",    "
						+ " hiu.organisation_id as \"organizationId\",    "
						+ " hiu.decrypted_data as \"decryptedData\",    "
						+ " hiu.encrypted_data as \"encryptedData\",    " + " hiu.unit_id as \"unitId\" "
						+ " from abdm.m_hiu_fhir_details hiu " + " where hiu.transaction_id =:transactionId ";
				List<AbdmCredentialdDto> listDecryptedDetails = sessionFactory.getCurrentSession()
						.createSQLQuery(query1.toString()).setString("transactionId", dto.getTransactionId())
						.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).list();
				listDecryptedDetailsNew.addAll(listDecryptedDetails);
			}

			if (listDecryptedDetailsNew != null && listDecryptedDetailsNew.size() > 0) {
				return new Response(SUCCESS, SUCCESS_CODE, null, listDecryptedDetailsNew, null, null);
			} else {
				return new Response(ERROR, ERROR_CODE, "Connection Timeout", null, abdmCredentialdDto);
			}

		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

	}

