	@Override
	@Transactional
	public Response getPatientDataByPatientId(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {

			String query = " select "
					+ "    concat(coalesce(patReg.first_name,'') ,' ', coalesce(patReg.middle_name,'') ,' ', coalesce(patReg.last_name,'')) as \"patientName\", "
					+ " 	to_char(patReg.dob, 'MM/DD/YYYY') as \"dob\", "
					+ " 	patReg.mobile_number as \"mobileNumber\", "
					+ " 	patReg.health_number as \"healthNumber\", " + " 	gen.gender_code as \"genderCode\", "
					+ " 	patReg.health_id as \"healthId\" " + " from " + " 	patient.t_patient_registration patReg "
					+ " inner join patient.t_patient_details patDtls on " + " 	patReg.patient_id = patDtls.patient_id "
					+ "  INNER JOIN public.t_unit_application_billing_configuration uabc on patReg.unit_id = uabc.unit_id "
					+ " inner join public.m_gender_master gen on " + " 	patReg.gender_id = gen.gender_id "
					+ " left join public.m_state_master sm on " + " 	sm.state_id = patDtls.state_id "
					+ " left join public.m_country_master com on " + " 	com.country_id = patDtls.country_id "
					+ " left join public.m_city_master cm on " + " 	cm.city_id = patDtls.city_id "
					+ " left join public.m_area_master areaS on " + "	areaS.area_id  = patDtls.area_id"
					+ " left outer join public.m_prefix_master preFix on " + " 	patReg.prefix_id = preFix.prefix_id "
					+ " left outer join adt.m_identification_master identi on "
					+ " 	patReg.identification_type_id = identi.identification_id "
					+ " left join adt.t_admission ta on ta.status = 'A' and ta.unit_id =:unitId and ta.patient_id = patReg.patient_id "
					+ " where " + " 	patReg.organization_id =:organizationId"
					+ " 	and patReg.patient_id =:patientId" + " 	and patReg.unit_id =:unitId"
					+ "    and patDtls.status ='A' ";

			AbdmCredentialdDto abdmCredentialdDtoswer = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery(query).setInteger("unitId", abdmCredentialdDto.getUnitId())
					.setInteger("organizationId", abdmCredentialdDto.getOrganizationId())
					.setInteger("patientId", abdmCredentialdDto.getPatientId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();

			return new Response(SUCCESS, SUCCESS_CODE, null, null, abdmCredentialdDtoswer, null);
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

