				AbdmCredentialdDto AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
				String accessToken = AsdbdmCredentialdDto.getAccessToken();

				JSONObject notification = new JSONObject();
				for (int i = 0; i < hTypeArray.length(); i++) {

					JSONObject careContextObject = new JSONObject();
					careContextObject.put("referenceNumber",
							abdmCredentialdDto.getEncounterNumber() + "/" + hTypeArray.get(i).toString());

					JSONObject careContext = new JSONObject();
					careContext.put("careContextReference",
							abdmCredentialdDto.getEncounterNumber() + "/" + hTypeArray.get(i).toString());
					careContext.put("patientReference", abdmCredentialdDto.getUhidNumber());

					notification.put("careContext", careContext);
				}

				// Add date to notification
				notification.put("date", abdmCredentialdDto.getTimeStamp());

				// Add hiTypes array to notification
				// JSONArray hiTypes = new JSONArray();
				// hiTypes.put(abdmCredentialdDto.getHiTypes());
				notification.put("hiTypes", hTypeArray);

				// Create the hip object and add it to notification
				JSONObject hip = new JSONObject();
				hip.put("id", abdmCredentialdDto.getHipId());
				notification.put("hip", hip);

				// Create the patient object and add it to notification
				JSONObject patient = new JSONObject();
				patient.put("id", abdmCredentialdDto.getHealthId());
				notification.put("patient", patient);

				// Wrap in the final JSON structure
				JSONObject finalJson = new JSONObject();
				finalJson.put("notification", notification);

				// Print the final JSON object
				System.out.println("FINAL Json .... Notify: " + finalJson.toString(2)); // Pretty
																						// print
																						// with
																						// 2
																						// spaces

				OkHttpClient client = new OkHttpClient().newBuilder().build();
				MediaType mediaType = MediaType.parse("application/json");
				RequestBody body = RequestBody.create(mediaType, finalJson.toString());
				Request request = new Request.Builder().url(url).method("POST", body)
						.addHeader("REQUEST-ID", uuidString).addHeader("TIMESTAMP", formattedTime)
						.addHeader("X-HIP-ID", abdmCredentialdDto.getHipId())
						.addHeader("X-LINK-TOKEN", abdmCredentialdDto.getTokenType())
						.addHeader("X-CM-ID", abdmCredentialdDto.getXcmId())
						.addHeader("Content-Type", "application/json")
						.addHeader("Authorization", "Bearer " + abdmCredentialdDto.getToken()).build();

