	@Override
	@org.springframework.transaction.annotation.Transactional
	public Response saveCarecontextOnNotify(AbdmCredentialdDto abdmCredentialdDto)
			throws ApplicationException, Exception {
		try {
			UUID uuid = UUID.randomUUID();
			String uuidString = uuid.toString();
			Instant currentTime = Instant.now();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
			String formattedTime = currentTime.atZone(java.time.ZoneOffset.UTC).format(formatter);
			abdmCredentialdDto.setEventId(abdmCredentialdDto.getEventId());
			Response masterRes = util.getAbdmUrlDetails(abdmCredentialdDto);
			AbdmCredentialdDto master = (AbdmCredentialdDto) masterRes.getObject();
			String accessToken = null;
			AbdmCredentialdDto AsdbdmCredentialdDto = null;
			AbdmCredentialdDto abdmCredentialdDtoswer = (AbdmCredentialdDto) sessionFactory.getCurrentSession()
					.createSQLQuery(
							"select ddcds.client_id as \"clientId\", ddcds.client_secret as \"clientSecret\" ,ddcds.dev_url as \"devUrl\" , ddcds.organization_id as \"organizationId\", ddcds.unit_id as \"unitId\" "
									+ " from abdm.m_abdm_credential ddcds " + " where ddcds.id =:id")
					.setString("id", abdmCredentialdDto.getHipId())
					.setResultTransformer(Transformers.aliasToBean(AbdmCredentialdDto.class)).uniqueResult();

			if (abdmCredentialdDtoswer != null) {

				abdmCredentialdDto.setOrganizationId(abdmCredentialdDtoswer.getOrganizationId());
				abdmCredentialdDto.setUnitId(abdmCredentialdDtoswer.getUnitId());
				Response refsvv = getCredentialDetails(abdmCredentialdDto);
				if (refsvv.getStatus().equals(SUCCESS) && refsvv.getObject() != null) {
					AsdbdmCredentialdDto = (AbdmCredentialdDto) refsvv.getObject();
					accessToken = AsdbdmCredentialdDto.getAccessToken();
				}

				String url = master.getBaseUrl() + master.getBasePath() + master.getApiUrl();

				ObjectMapper objectMapper = new ObjectMapper();
				JsonNode jsonNode = objectMapper.readTree(abdmCredentialdDto.getCarecontextOnNotifyJson());
				String status = jsonNode.path("acknowledgement").path("status").asText();
				String requestId = jsonNode.path("response").path("requestId").asText();

				JSONObject jsonObject = new JSONObject();

				// Add root-level properties
				jsonObject.put("requestId", uuidString);
				jsonObject.put("timestamp", formattedTime);

				// Create the acknowledgement object
				JSONObject acknowledgement = new JSONObject();
				acknowledgement.put("status", status);

				// Add acknowledgement to the root JSON object
				jsonObject.put("acknowledgement", acknowledgement);

				// Create the response object
				JSONObject response = new JSONObject();
				response.put("requestId", requestId);

				// Add response to the root JSON object
				jsonObject.put("response", response);

				// Print the JSON object
				System.out.println(jsonObject.toString(2)); // Pretty print with
															// 2 spaces

				OkHttpClient client = new OkHttpClient().newBuilder().build();
				MediaType mediaType = MediaType.parse("application/json");
				RequestBody body = RequestBody.create(mediaType, jsonObject.toString());
				Request request = new Request.Builder().url(url).method("POST", body)
						.addHeader("X-CM-ID", AsdbdmCredentialdDto.getXcmId())
						.addHeader("Content-Type", "application/json")
						.addHeader("Authorization", "Bearer " + accessToken + " ").addHeader("REQUEST-ID", uuidString)
						.addHeader("TIMESTAMP", formattedTime).build();
				okhttp3.Response response1 = client.newCall(request).execute();
				if (response1.code() == 202) {
					String resBOdy = response1.body().toString();
					System.out.println("response Body " + resBOdy);
					System.out.println("response Body and Code " + response1.code());

					return new Response(SUCCESS, SUCCESS_CODE, null, null, resBOdy);
				} else {
					return new Response(ERROR, String.valueOf(response1.code()), response1.message(), null, null);
				}

			}
		} catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}

		return new Response(ERROR, ERROR_CODE, null, null, null, null);

	}

