	private String encryptForV3Integer(Integer index, String publicKeyString) {
	    try {
	        // Decode the public key string
	        byte[] publicKeyBytes = Base64.getDecoder().decode(publicKeyString.getBytes());
	        KeyFactory keyFactory = KeyFactory.getInstance("RSA");
	        X509EncodedKeySpec publicKeySpec = new X509EncodedKeySpec(publicKeyBytes);
	        PublicKey publicKey = keyFactory.generatePublic(publicKeySpec);

	        // Initialize the cipher
	        Cipher cipher = Cipher.getInstance("RSA/ECB/OAEPWithSHA-1AndMGF1Padding", "BC");
	        cipher.init(Cipher.ENCRYPT_MODE, publicKey);

	        // Convert the Integer to a String and then encrypt it
	        String indexAsString = index.toString(); // Convert Integer to String
	        byte[] encryptedBytes = cipher.doFinal(indexAsString.getBytes(StandardCharsets.UTF_8));

	        // Encode the encrypted bytes to Base64
	        String encodedValue = Base64.getEncoder().encodeToString(encryptedBytes);
	        return encodedValue;
	    } catch (Exception e) {
			logger.error(e.getMessage(), e);
			throw new ServiceException(e.getMessage());
		}
	}

